DOCUMENT();

#############
# Load Macros
#############

loadMacros(
  "PGstandard.pl",
  "PGML.pl",
  "AnswerFormatHelp.pl",
  "PGlateximage.pl",
  "PCCmacros.pl",
  "parserImplicitPlane.pl",
  "contextForm.pl",
  "contextFraction.pl",
  "parserGraphTool.pl",
  "ORCCA.pl",
  "PGcourse.pl",
);
COMMENT('Authored in PreTeXt');

#######
# Setup
#######

@x = random_subset(2, -5..5);
@y = random_subset(2, -5..5);
Context("Fraction");
$m[0] = Fraction(($y[1] - $y[0]) / ($x[1] - $x[0]));
do {
  do {
    $x[2] = random(-9,9);
    $y[2] = random(-9,9);
  } until ($x[2] != $x[0] && ($y[2] - $y[0]) / ($x[2] - $x[0]) != $m[0]);
  $d = ($m[0]->value)[1];
  $x[3] = $x[2] + non_zero_random(-3,3)*$d;
  $y[3] = $y[2] + ($x[3] - $x[2])*$m[0];
} until (abs($x[3]) <= 9 && abs($y[3]) <= 9);
@p = map {Point($x[$_],$y[$_])} (0..3);
Context("ImplicitPlane")->variables->are(x =>'Real', y => 'Real');
$eq = Compute("y = $m[0](x - $x[2]) + $y[2]");
$gt = GraphTool("{line,solid,$p[2],$p[3]}")->with(
  staticObjects => ["{line,solid,$p[0],$p[1]}", "{point,$p[0]}", "{point,$p[1]}"],
  availableTools => [ "LineTool" ],
  showCoordinateHints => 0,
  showInStatic => 0,
);
$f = Formula("$m[0](x - $x[2]) + $y[2]")->reduce;
@domain = num_sort(-10, 10, (-10 - $y[2])/$m[0] + $x[2], (10 - $y[2])/$m[0] + $x[2]);
($l,$r) = (@domain)[1,2];

$image_1 = createLaTeXImage();
$image_1->addToPreamble(latexImagePreamble());
$image_1->BEGIN_LATEX_IMAGE
\begin{tikzpicture}
  \begin{axis}[
      xmin=-10,
      xmax=10,
      ymin=-10,
      ymax=10,
      xtick={-10,-5,5,10},
      ytick={-10,-5,5,10},
      minor xtick={-10,...,10},
      minor ytick={-10,...,10},
      width=0.47\orccaprintwidth,
    ]
    \addplot+[domain=$l:$r] {$f};
  \end{axis}
\end{tikzpicture}

END_LATEX_IMAGE

#############################
# Exercise Group Introduction
#############################

BEGIN_PGML
Write an equation for the line that is described. Then plot that line.

END_PGML

######
# Body
######

BEGIN_PGML
A line is parallel to the line passing through [`[$p[0]]`] and [`[$p[1]]\text{,}`] and passes through [`[$p[2]]\text{.}`]

[@KeyboardInstructions('Enter an equation for the line here.')@]**

[_]{$eq}{16}

[@KeyboardInstructions('Now plot the line.')@]**

[_]{$gt}{1}

END_PGML

##########
# Solution
##########

BEGIN_PGML_SOLUTION
Based on the points [`[$p[0]]`] and [`[$p[1]]\text{,}`] the first line has slope [`[$m[0]]\text{.}`] But the lines are parallel, so the second line also has slope [`[$m[0]]\text{.}`] The second line passes through [`[$p[2]]\text{,}`] so we can use point-slope form to write an equation for it: [`y=[$f]\text{.}`] To plot this, we can start at [`[$p[2]]`] and use slope triangles.

>> [@image(insertGraph($image_1), width=>282)@]*  <<

END_PGML_SOLUTION

#############
# End Problem
#############

